using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Security.Cryptography;using System.Threading;using System.Threading.Tasks;
namespace FoolLauncher {public static class VanillaTests {
 static void Assert(bool v,string m){if(!v)throw new Exception(m);}static void Reject(Action a){bool caught=false;try{a();}catch(IOException){caught=true;}catch(InvalidDataException){caught=true;}catch(OperationCanceledException){caught=true;}Assert(caught,"Unsafe vanilla metadata accepted");}
 public static void Run(string root){var service=new PackService(Path.Combine(root,"vanilla"));string id="1.14 Pre-Release 5";byte[] metadata=Encoding.UTF8.GetBytes("{\"id\":\""+id+"\"}");string hash;using(var sha=SHA1.Create())hash=BitConverter.ToString(sha.ComputeHash(metadata)).Replace("-","").ToLowerInvariant();var version=new VanillaVersion{id=id,type="snapshot",url="https://piston-meta.mojang.com/v1/packages/fixture.json",sha1=hash,releaseTime="2019-04-10T12:00:00Z"};var manifest=new VanillaManifest{latest=new Dictionary<string,string>{{"release","1.20.1"}},versions=new[]{version}};string json=new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(manifest);byte[] bytes=Encoding.UTF8.GetBytes(json);Assert(VanillaService.Parse(bytes).versions.Single().id==id,"Historical ID with spaces lost");var api=new VanillaService(service,(url,ct)=>{ct.ThrowIfCancellationRequested();return Task.FromResult(url==VanillaService.ManifestUrl?bytes:metadata);});var listed=api.List(CancellationToken.None).GetAwaiter().GetResult();api.Verify(version,CancellationToken.None).GetAwaiter().GetResult();var instance=api.Prepare(version);Assert(instance.Loader=="原版"&&!instance.Ready&&service.Index(instance).dependencies.Count==1&&service.List().Count==1,"Vanilla instance not safely created in library");File.WriteAllText(Path.Combine(service.Game(instance),"sentinel.txt"),"preserve");Assert(api.Prepare(version).Id==instance.Id&&File.ReadAllText(Path.Combine(service.Game(instance),"sentinel.txt"))=="preserve","Repeat download created/overwrote instance");var pack=Json.Read<MetaComponents>(Path.Combine(service.Folder(instance),"mmc-pack.json"));Assert(pack.components.Length==1&&pack.components[0].version==id,"Vanilla Prism components incorrect");Assert(MetadataCache.DependencyVersion(new MetaRequirement{uid="net.minecraft",equals=id},new Dictionary<string,string>{{"net.minecraft",id}})==id,"Metadata rejects spaced historic version");
  var offline=new VanillaService(service,(url,ct)=>{throw new IOException("offline");});Assert(offline.List(CancellationToken.None).GetAwaiter().GetResult().versions.Length==1&&offline.Cached,"Offline manifest cache failed");using(var c=new CancellationTokenSource()){c.Cancel();Reject(()=>api.List(c.Token).GetAwaiter().GetResult());}Reject(()=>VanillaService.Parse(Encoding.UTF8.GetBytes(json.Replace("piston-meta.mojang.com","evil.example"))));Reject(()=>VanillaService.Parse(Encoding.UTF8.GetBytes(json.Replace(hash,"bad"))));foreach(string bad in new[]{"../outside","CON","a/b","bad:version"," leading"})Reject(()=>VanillaService.VersionId(bad));var corrupt=new VanillaService(service,(url,ct)=>Task.FromResult(Encoding.UTF8.GetBytes("{}")));Reject(()=>corrupt.Verify(version,CancellationToken.None).GetAwaiter().GetResult());Console.WriteLine("PASS: official vanilla manifest, historic IDs with spaces, HTTPS/hash/path validation, offline cache/cancellation, isolated vanilla components and repeat-install preservation.");}
}}
